import test from "node:test";
import assert from "node:assert/strict";
import React from "react";
import { renderToStaticMarkup } from "react-dom/server";

// Markdown.res.mjs is generated by `rescript build` (run as part of `npm run build`).
import * as Markdown from "../client/src/components/Markdown.res.mjs";

const render = (text) => renderToStaticMarkup(React.createElement(Markdown.make, { text }));

test("renders bold inside a paragraph", () => {
  const html = render("Hello **world**");
  assert.match(html, /<strong[^>]*>world<\/strong>/);
  assert.match(html, /<p[^>]*>/);
});

test("renders italic and inline code", () => {
  assert.match(render("an _emphasis_ here"), /<em[^>]*>emphasis<\/em>/);
  assert.match(render("run `npm run build` now"), /<code[^>]*>npm run build<\/code>/);
});

test("renders an unordered list with one <li> per item", () => {
  const html = render("* one\n* two\n* three");
  assert.match(html, /<ul[^>]*>/);
  assert.equal((html.match(/<li[^>]*>/g) || []).length, 3);
});

test("renders an ordered list", () => {
  const html = render("1. first\n2. second");
  assert.match(html, /<ol[^>]*>/);
  assert.equal((html.match(/<li[^>]*>/g) || []).length, 2);
});

test("renders a fenced code block verbatim", () => {
  const html = render("```\nline1\nline2\n```");
  assert.match(html, /<pre[^>]*>[\s\S]*line1[\s\S]*line2[\s\S]*<\/pre>/);
});

test("allows safe links and keeps the href", () => {
  const html = render("see [my site](https://arda.tr)");
  assert.match(html, /<a [^>]*href="https:\/\/arda\.tr"[^>]*>my site<\/a>/);
});

test("drops javascript: links to plain text (no anchor, no scheme leak)", () => {
  const html = render("[click](javascript:alert(1))");
  assert.doesNotMatch(html, /<a /);
  assert.doesNotMatch(html, /javascript:/);
  assert.match(html, /click/);
});

test("escapes raw HTML so model output cannot inject markup", () => {
  const html = render('<img src=x onerror="alert(1)">');
  assert.doesNotMatch(html, /<img/);
  assert.match(html, /&lt;img/);
});

test("empty input renders without throwing", () => {
  assert.doesNotThrow(() => render(""));
});

// The bot separates numbered items with blank lines and indents sub-points
// under them. Each of those used to start a new <ol>, so the reader saw
// "1. 1. 1.".
test("an ordered list stays one list across blank lines", () => {
  const html = render("1. Go\n\n2. Ruby\n\n3. Python");
  assert.equal((html.match(/<ol[\s>]/g) || []).length, 1);
  assert.equal((html.match(/<li[^>]*>/g) || []).length, 3);
});

test("an indented sub-list nests inside its item and the numbering continues", () => {
  const html = render("1. Go\n   - fast builds\n   - small binaries\n2. Ruby\n\n   - Rails\n3. Python");
  assert.equal((html.match(/<ol[\s>]/g) || []).length, 1, "one ordered list");
  assert.match(html, /<li[^>]*>Go<ul[^>]*><li[^>]*>fast builds<\/li><li[^>]*>small binaries<\/li><\/ul><\/li>/);
  assert.match(html, /<li[^>]*>Ruby<ul[^>]*><li[^>]*>Rails<\/li><\/ul><\/li><li[^>]*>Python<\/li><\/ol>/);
});

test("an ordered list interrupted by a paragraph resumes at its number", () => {
  const html = render("1. Go\n\nA note.\n\n2. Ruby");
  assert.match(html, /<ol[^>]*start="2"[^>]*><li[^>]*>Ruby<\/li>/);
});

test("underscores and asterisks inside words or between spaces are not emphasis", () => {
  for (const text of ["call snake_case_name here", "2 * 3 * 4 = 24", "a_b and c_d", "x*y*z"]) {
    const html = render(text);
    assert.doesNotMatch(html, /<em/, text);
    assert.ok(html.includes(text), `expected "${text}" verbatim`);
  }
  assert.match(render("an _emphasis_ and a *stress*."), /<em[^>]*>emphasis<\/em> and a <em[^>]*>stress<\/em>\./);
});

test("a link URL may contain balanced parentheses", () => {
  const html = render("see [Go](https://en.wikipedia.org/wiki/Go_(programming_language)) now");
  assert.match(html, /href="https:\/\/en\.wikipedia\.org\/wiki\/Go_\(programming_language\)"[^>]*>Go<\/a> now/);
});

test("unsafe links stay plain text inside nested list items too", () => {
  const html = render("1. ok\n   - [x](javascript:alert(1))");
  assert.doesNotMatch(html, /<a /);
  assert.doesNotMatch(html, /javascript:/);
});

// A bullet and a numbered step under the same item are two nested lists, not
// one list of whichever kind came first.
test("mixed nested lists keep their own kinds, and the outer list stays whole", () => {
  const html = render("1. parent\n   - bullet\n   1. step\n2. next");
  assert.match(
    html,
    /^<div[^>]*><ol[^>]*><li>parent<ul[^>]*><li>bullet<\/li><\/ul><ol[^>]*><li>step<\/li><\/ol><\/li><li>next<\/li><\/ol><\/div>$/
  );

  const reverse = render("- a\n   1. one\n   - b\n- c");
  assert.match(
    reverse,
    /^<div[^>]*><ul[^>]*><li>a<ol[^>]*><li>one<\/li><\/ol><ul[^>]*><li>b<\/li><\/ul><\/li><li>c<\/li><\/ul><\/div>$/
  );
});

test("a nested ordered list keeps its start number", () => {
  const html = render("1. a\n   - note\n   3. x\n   4. y\n2. b");
  assert.match(html, /<li>a<ul[^>]*><li>note<\/li><\/ul><ol[^>]*start="3"[^>]*><li>x<\/li><li>y<\/li><\/ol><\/li><li>b<\/li>/);
});

// Japanese has no spaces between words, so a boundary rule that counts kana
// and kanji as word characters makes `*` emphasis impossible in Japanese.
// As in CommonMark, `*` only needs to avoid ASCII letters and digits, while
// `_` keeps the Unicode rule (snake_case stays text in any script).
test("single-asterisk emphasis works between Japanese characters", () => {
  assert.match(render("これは*重要*です"), /これは<em[^>]*>重要<\/em>です/);
  assert.match(render("「*注意*」してください"), /「<em[^>]*>注意<\/em>」/);
  assert.match(render("Goと*Rust*で書く"), /Goと<em[^>]*>Rust<\/em>で書く/);
  for (const text of ["rust_on_rails", "x*y*z", "2 * 3 * 4", "a*b* c", "これは_重要_です"]) {
    const html = render(text);
    assert.doesNotMatch(html, /<em/, text);
    assert.ok(html.includes(text), `expected "${text}" verbatim`);
  }
});

// The bot bolds a link to a project, or bolds a link's label. Both used to
// print their inner markers literally. One level of nesting is parsed; the
// inner marks go through the same element-only renderer and link allow-list.
test("bold, italic and link labels may hold one level of inline marks", () => {
  assert.match(
    render("see **[golem](https://x.y)** now"),
    /see <strong><a [^>]*href="https:\/\/x\.y"[^>]*>golem<\/a><\/strong> now/
  );
  assert.match(render("[**label**](https://x.y)"), /<a [^>]*href="https:\/\/x\.y"[^>]*><strong>label<\/strong><\/a>/);
  assert.match(render("**bold and _it_ and `code`**"), /<strong>bold and <em>it<\/em> and <code[^>]*>code<\/code><\/strong>/);
  assert.match(render("_see [x](https://x.y)_"), /<em>see <a [^>]*>x<\/a><\/em>/);
  // Inner marks never smuggle in an unsafe link or raw HTML.
  const unsafe = render("**[x](javascript:alert(1))** and **<img src=x>**");
  assert.doesNotMatch(unsafe, /<a |javascript:|<img/);
  assert.match(unsafe, /<strong>x<\/strong>/);
  // An unsafe link keeps its label, marks included, as text.
  assert.match(render("[**y**](javascript:alert(1))"), /<strong>y<\/strong>/);
  // Deeper nesting stays literal rather than recursing without bound.
  assert.match(render("**_[a](https://x.y)_**"), /<strong><em>\[a\]\(https:\/\/x\.y\)<\/em><\/strong>/);
});
